<?php
declare(strict_types=1);namespace App\Application\Discovery\Service;use App\Application\Discovery\DTO\Request\CreateDiscoverySearchRequestDto;use App\Application\Discovery\DTO\Response\DiscoveryResourceResponseDto;use App\Application\Discovery\Mapper\DiscoveryResponseMapper;use App\Application\Discovery\Port\WebDiscoveryProviderInterface;use App\Domain\Discovery\Entity\DiscoveryResource;use App\Domain\Discovery\Repository\DiscoveryResourceRepositoryInterface;final class DiscoverWebResourcesService{public function __construct(private readonly DiscoveryResourceRepositoryInterface $resources,private readonly WebDiscoveryProviderInterface $provider,private readonly DiscoveryResponseMapper $mapper){}public function discover(CreateDiscoverySearchRequestDto $input):array{if(mb_strlen(trim($input->query))<3)throw new \DomainException('A consulta deve ter ao menos 3 caracteres.');$out=[];foreach(array_slice($this->provider->search(trim($input->query),$input->type),0,10) as $item){$resource=new DiscoveryResource(bin2hex(random_bytes(16)),$item->type,$item->title,$item->sourceUrl,$this->provider->name(),trim($input->query),new \DateTimeImmutable('now'));$this->resources->save($resource);$out[]=$this->mapper->resource($resource);}return $out;}}
